			}),
			title: Type.Optional(
				Type.String({
					description:
						"A few words naming what this shows, displayed above the diagram.",
				}),
			),
			notes: Type.Optional(
				Type.String({
					description:
						"One optional line under the diagram for what the picture cannot say — a caveat, a legend, what to look at first.",
				}),
			),
		}),
		async execute(_toolCallId, params) {
			if (!DIAGRAM_URL) {
				return {
					content: [
						{
							type: "text",
							text: "No SWITCHBOARD_DIAGRAM_URL is set, so there is no screen to draw on. Describe the structure in words instead.",
						},
					],
					details: {},
					isError: true,
				};
			}
			try {
				const resp = await fetch(DIAGRAM_URL, {
					method: "POST",
					headers: { "Content-Type": "application/json" },
					body: JSON.stringify({
						source: params.source,
						title: params.title ?? "",
						notes: params.notes ?? "",
					}),
					signal: AbortSignal.timeout(30_000),
				});
				if (!resp.ok) {
					return {
						content: [
							{
								type: "text",
								text: `The switchboard refused that diagram (HTTP ${resp.status}).`,
							},
						],
						details: {},
						isError: true,
					};
				}
				const data = (await resp.json()) as {
					delivered?: boolean;
					reason?: string;
				};
				if (data.delivered === false) {
					// Not an error — nobody has the page open. The diagram is held and
					// shown if they open one, so this is information, not a failure.
